# Static imports fingerprint images; Next serves these as immutable assets.
files={'care-hero':'care-hero.jpg','skin-study':'skin-study.jpg','treatment-facial':'treatment-facial.jpg','treatment-aesthetic':'treatment-aesthetic.jpg','hair-study':'hair-study.jpg','nutrition-study':'nutrition-study.jpg','bridal-study':'bridal-study.jpg','hair':'hair.jpg'}
imports=[];mapping=[]
for i,(name,file) in enumerate(files.items()):imports.append(f"import photo{i} from '../public/images/{file}';");mapping.append(f"'{name}':photo{i}")
for name in art:imports.append(f"import {name} from '../public/illustrations/{name}.svg';");mapping.append(f"'topic-{name}':{name}")
put('lib/media.ts', '\n'.join(imports)+"\nimport type {StaticImageData} from 'next/image';\nexport const media:Record<string,StaticImageData>={"+','.join(mapping)+"};\nexport const articleImages:Record<string,string>={'choose-skin-specialist-mirpur':'topic-specialist','hydrafacial-mirpur':'topic-hydrafacial','acne-scars-pigmentation':'topic-acne','laser-hair-removal':'topic-laser','prp-for-hair':'topic-prp'};\n")
put('components/Photo.tsx','''import Image from 'next/image';import {media} from '@/lib/media';
const aliases:Record<string,string>={portrait:'treatment-aesthetic',skin:'skin-study',still:'nutrition-study','treatment-laser':'topic-laser'};
const descriptions:Record<string,string>={'care-hero':'Facial care application — illustrative stock, not a Revive patient or facility','skin-study':'Aesthetic care detail — illustrative stock photography','nutrition-study':'Fresh ingredients — illustrative nutrition photography','topic-specialist':'Concept illustration of a consultation record and discussion','topic-hydrafacial':'Concept illustration of a facial handpiece and hydration','topic-acne':'Concept illustration exploring skin texture and tone, not a clinical diagram','topic-laser':'Concept illustration of a light-based hair removal handpiece and hair follicle','topic-prp':'Concept illustration of a prepared plasma tube and hair study, not a treatment result'};
export default function Photo({name='portrait',className='',priority=false,sizes='(max-width: 767px) 88vw, 50vw'}:{name?:string;className?:string;priority?:boolean;sizes?:string}){const key=aliases[name]||name;const src=media[key]||media['skin-study'];return <div className={`photo ${className}`}><Image src={src} alt={descriptions[key]||'Illustrative editorial study — not Revive staff, facilities or patient results'} fill sizes={priority?'100vw':sizes} preload={priority} placeholder={src.blurDataURL?'blur':'empty'} quality={75}/></div>}
''')
p=r/'components/JournalCards.tsx';s=p.read_text(encoding='utf-8');a=s.index('<Photo name=');b=s.index('/>',a)+2;s=s[:a]+'''<Photo name={articleImages[a.slug]} sizes="(max-width: 767px) 88vw, 28vw"/>'''+s[b:];s="import {articleImages} from '@/lib/media';\n"+s;put('components/JournalCards.tsx',s)
p=r/'components/Article.tsx';s=p.read_text(encoding='utf-8').replace('<Photo name={a.image}/>','<Photo name={articleImages[a.slug]} sizes="86vw"/>');put('components/Article.tsx',"import {articleImages} from '@/lib/media';\n"+s)
p=r/'components/Treatments.tsx';s=p.read_text(encoding='utf-8').replace('<Photo name={c.image}/>','<Photo name={c.image} sizes="90vw"/>');put('components/Treatments.tsx',s)
# Remove all remaining text-glyph icons, including secondary routes and drafts.
for p in [*(r/'app').rglob('*.tsx'),*(r/'components').glob('*.tsx')]:
 s=p.read_text(encoding='utf-8');used=[]
 for glyph,icon in [('↗','ArrowUpRight'),('←','ArrowLeft')]:
  if glyph in s:s=s.replace(glyph,f'<{icon} size={{18}} aria-hidden="true"/>');used.append(icon)
 if used:
  statement="import {"+','.join(used)+"} from 'lucide-react';\n"
  if "'use client';" in s:s=s.replace("'use client';","'use client';\n"+statement,1)
  else:s=statement+s
  p.write_text(s,encoding='utf-8')
# Native browser scrolling: no interceptors, tickers, or observer-driven stop states.
p=r/'app/layout.tsx';s=p.read_text(encoding='utf-8').replace("import SmoothScroll from '@/components/SmoothScroll';",'').replace('<SmoothScroll/>','');put('app/layout.tsx',s)
put('components/SmoothScroll.tsx',"// Native browser scrolling is intentional. No wheel interception or animation-frame scroll loop.\nexport default function SmoothScroll(){return null}\n")
